+fn block(world: &World, w: f64, z0: f64, dz: f64) -> SetStock {
+    let at = Location { pos: Point3::new(5.0, 5.0, z0), ..Default::default() };
+    SetStock::new(world, StockShape::Box { dx: w, dy: w, dz }, at).expect("stock")
+}
